{
  "ledger": {
    "p45:e303": {
      "state": "represented",
      "fact_ids": ["P0045R0F0001"],
      "note": "Nsight System의 kernel 비중 증가와 메모리 비중 감소 시, 이것이 최적화 성공인지 커널 자체 비효율로 인한 실행시간 증가인지 원인 분석이 필요하다는 해석적 주의 사항."
    },
    "p45:e305": {
      "state": "represented",
      "fact_ids": ["P0045R0F0002"],
      "note": "kernel/메모리 throughput 해석 관련 정정 내용을 다음 세미나에 포함하기로 한 계획 메모. 연구 사실이 아닌 세미나 발표 계획/의도."
    },
    "p45:e306": {
      "state": "represented",
      "fact_ids": ["P0045R0F0003"],
      "note": "이전 발표에서 Nsight system의 kernel 비중은 커질수록 좋고, Nsight compute의 compute throughput은 높아지면 이유를 분석해보고 좋은지 판단해야 한다고 말했으나 잘못된 부분이 있다고 정정한 내용."
    },
    "p45:e307": {
      "state": "represented",
      "fact_ids": ["P0045R0F0004"],
      "note": "kernel 비중도 Compute throughput처럼 최적화 결과인지 원인 분석 후 판단해야 하며, 메모리 throughput도 최적화 성공인지 메모리 활용 부족인지 분석 후 판단해야 한다는 정정·주의 내용. CPU-GPU 메모리 병목 유지 상태에서 커널 실행 시간 증가 가능성도 함께 언급."
    },
    "p45:e309": {
      "state": "represented",
      "fact_ids": ["P0045R0F0005"],
      "note": "forward 테스트 수행 사실을 heading 수준으로 진술. 구체적인 측정 결과는 별도 요소(p45:e313 등)에 기술됨."
    },
    "p45:e311": {
      "state": "represented",
      "fact_ids": ["P0045R0F0006"],
      "note": "crown_test_optimizing과 동일하게 실행했다는 조건 진술. 구체적인 동일 조건 세부 사항은 별도 요소에 의존."
    }
  }
}
